assert.equal(r.extent,64);assert.equal(r.rampModes.length,3);for(let mode=0;mode<3;mode++)for(let c=0;c<3;c++){assert.equal(r.rampModes[mode][c].length,256);for(let i=0;i<256;i++){const v=r.rampModes[mode][c][i];assert(Number.isInteger(v)&&v>=0&&v<=65535);if(!mode)assert.equal(v,i*257);if(i)assert(v>=r.rampModes[mode][c][i-1]);}}assert.equal(r.frames.length,8);assert.deepEqual(r.frames.map(f=>f.mode),[0,1,1,1,0,0,2,2]);assert.deepEqual(r.frames.map(f=>f.windowed),[1,1,1,0,0,1,1,1]);for(const f of r.frames){assert.equal(f.rawARGB,0xff80a0c0);assert.deepEqual(f.displayRGBA,[128,160,192].map((v,c)=>Math.round(r.rampModes[f.mode][c][v]/257)).concat(255));}assert.equal(r.rampSequence.length,7);assert.deepEqual(r.flagSequence,[1,0,1,1,0,0,0]);assert.match(r.scope,/Physical OS display calibration/);assert.equal(r.sources.length,3);for(const s of r.sources){assert.match(s.sha256,/^[a-f0-9]{64}$/);assert.match(s.blobSha1,/^[a-f0-9]{40}$/);}console.log("PASS independent gamma reference: three full WORD RGB curves, normalized LUT scanout, identity/live recording, eight frames/two Resets, raw preservation and explicit calibration scope");
